(async () => {
  if (window.__booted) return {booted: 'already', bodies: window.__bodies.length};
  window.__bodies = [];
  const sniff = (u) => String(u).includes('queryboughtlistv2');
  const of = window.fetch;
  window.fetch = function(u, o) {
    const r = of.apply(this, arguments);
    try { if (sniff(u) || sniff(o && o.url)) r.clone().text().then(t => window.__bodies.push(t)).catch(()=>{}); } catch(e) {}
    return r;
  };
  const OX = XMLHttpRequest.prototype.open, OS = XMLHttpRequest.prototype.send;
  XMLHttpRequest.prototype.open = function(m, u) { this.__u = u; return OX.apply(this, arguments); };
  XMLHttpRequest.prototype.send = function() {
    this.addEventListener('load', function() { try { if (sniff(this.__u)) window.__bodies.push(this.responseText); } catch(e) {} });
    return OS.apply(this, arguments);
  };
  let jsUrl = null, cssUrl = null;
  (function walk(x) {
    if (!x || typeof x !== 'object') return;
    if (typeof x.urlList === 'string') {
      for (const u of x.urlList.split(';')) {
        if (!jsUrl && /js\/main\.js$/.test(u)) jsUrl = u;
        if (!cssUrl && /css\/main\.css$/.test(u)) cssUrl = u;
      }
    }
    if (Array.isArray(x)) { for (const c of x) walk(c); }
    else if (typeof x === 'object') { for (const k of Object.keys(x)) walk(x[k]); }
  })((window.pcMyTaobaoMenuList && JSON.parse(window.pcMyTaobaoMenuList.replace(/&quot;/g, '"'))) || []);
  if (!jsUrl) return {error: 'no main.js in pcMyTaobaoMenuList'};
  if (cssUrl) { const l = document.createElement('link'); l.rel = 'stylesheet'; l.href = cssUrl; document.head.appendChild(l); }
  history.pushState(null, '', '/');
  const code = await (await of(jsUrl)).text();
  const s = document.createElement('script');
  s.textContent = code;
  document.head.appendChild(s);
  window.__booted = true;
  return {injected: code.length, jsUrl};
})()

(async () => {
  if (!window.__bodies || !window.__bodies.length) return {grew: false, why: 'session lost: no __bodies (redirected to login/punish?)', page: 0, bodies: 0, orders: 0};
  const parse = (b) => {
    try {
      const t = b.trim();
      const j = JSON.parse(t.startsWith('{') ? t : t.replace(/^\/\*\//, '').replace(/^[\w$.]+\s*\(/, '').replace(/\)\s*;?$/, ''));
      const data = (j.data && j.data.data) || {};
      const ids = new Set();
      for (const k of Object.keys(data)) { if (k.indexOf('shopInfo_') === 0) ids.add(k.slice(9)); }
      return {ids, pc: (j.data && j.data.global && j.data.global.pageControl) || null};
    } catch (e) { return {ids: new Set(), pc: null}; }
  };
  window.__seenIds = window.__seenIds || new Set();
  for (const b of window.__bodies) { for (const id of parse(b).ids) window.__seenIds.add(id); }
  const fire = (target) => {
    const ul = document.querySelector('.ant-pagination');
    if (!ul) return 'no pager';
    const fkey = Object.keys(ul).find(k => k.startsWith('__reactFiber$'));
    if (!fkey) return 'no fiber';
    let fiber = ul[fkey], hops = 0, onChange = null;
    while (fiber && hops < 12) {
      const pp = fiber.memoizedProps || {};
      if (typeof pp.onChange === 'function') { onChange = pp.onChange; break; }
      fiber = fiber.return; hops++;
    }
    if (!onChange) return 'no onChange';
    onChange(target, 30);
    return null;
  };
  const awaitBody = async (before) => {
    for (let i = 0; i < 40; i++) {
      if (window.__bodies.length > before) return window.__bodies[window.__bodies.length - 1];
      await new Promise(r => setTimeout(r, 500));
    }
    return null;
  };
  // Target page from the DATA, not the DOM: pageControl.nextPageIndex of the
  // last body is exactly the next page to ask for. antd's active item lags
  // arbitrarily when driven this way (seen showing 1 while on page 4).
  const last = parse(window.__bodies[window.__bodies.length - 1]);
  let target = (last.pc && last.pc.nextPageIndex) ? last.pc.nextPageIndex : (window.__bodies.length + 1);
  let why = null, fresh = null, round = 0;
  while (round < 2) {
    why = fire(target);
    if (why) break;
    fresh = await awaitBody(window.__bodies.length);
    if (!fresh) { why = 'no new body'; break; }
    const f = parse(fresh);
    let newIds = 0;
    for (const id of f.ids) { if (!window.__seenIds.has(id)) { newIds++; window.__seenIds.add(id); } }
    const hasMore = f.pc ? f.pc.hasMore : true;
    if (newIds > 0 || hasMore === false || round === 1) {
      await new Promise(r => setTimeout(r, 1500)); // settle: back-to-back onChange refetches the same page
      return {grew: newIds > 0 && hasMore !== false, newIds, hasMore, page: target, bodies: window.__bodies.length, orders: window.__seenIds.size};
    }
    target = target + 1; round = 1; // dup body while hasMore — re-fire at the next page once
  }
  return {grew: false, why: why || 'exhausted', page: target, bodies: window.__bodies.length, orders: window.__seenIds.size};
})()

(() => {
  const orders = {};
  let bad = 0;
  for (const b of window.__bodies) {
    let j = null;
    try {
      const t = b.trim();
      j = JSON.parse(t.startsWith('{') ? t : t.replace(/^\/\*\//, '').replace(/^[\w$.]+\s*\(/, '').replace(/\)\s*;?$/, ''));
    } catch (e) { bad++; continue; }
    const data = (j.data && j.data.data) || {};
    for (const k of Object.keys(data)) {
      if (k.indexOf('shopInfo_') === 0) {
        const oid = k.slice(9);
        const f = (data[k].fields) || {};
        const o = orders[oid] = orders[oid] || {orderId: oid};
        o.createTime = f.createTime; o.shopName = f.shopName || f.sellerNick;
      } else if (k.indexOf('orderItemInfo_') === 0) {
        const oid = k.slice(14).split('_')[0];
        const item = ((data[k].fields) || {}).item || {};
        const o = orders[oid] = orders[oid] || {orderId: oid};
        o.title = item.title; o.itemId = item.itemId; o.qty = item.quantity;
        o.paid = item.priceInfo && item.priceInfo.actualTotalFee;
        o.sku = item.skuText; o.url = item.itemUrl;
      }
    }
  }
  const list = Object.keys(orders).map(k => orders[k]).sort((a, b) => (b.createTime || '').localeCompare(a.createTime || ''));
  return {pages: window.__bodies.length, badBodies: bad, orders: list};
})()
